"""Pacing, ECG patterns and syncope decisions, Chapter 14 additions 16–35."""
from qbank_json_chapters import question
REFERENCES={
 'syncope':('ESC Syncope Guideline, 2018','https://doi.org/10.1093/eurheartj/ehy037'),
 'practical':('ESC Practical Instructions for Syncope, 2018','https://doi.org/10.1093/eurheartj/ehy071'),
 'pace':('ESC Cardiac Pacing and CRT Guideline, 2021','https://doi.org/10.1093/eurheartj/ehab364'),
 'va':('ESC Ventricular Arrhythmia/Sudden Death Guideline, 2022','https://doi.org/10.1093/eurheartj/ehac262'),
 'pots':('Canadian Cardiovascular Society Position Statement on POTS, 2020','https://doi.org/10.1016/j.cjca.2019.12.024'),
 'post4':('Midodrine for Prevention of Vasovagal Syncope: POST-4, 2021','https://pubmed.ncbi.nlm.nih.gov/34339231/'),
 'biosync':('BioSync CLS randomized trial, 2021','https://pubmed.ncbi.nlm.nih.gov/33279955/'),
 'udmi':('Fifth Universal Definition of MI, 2026','https://doi.org/10.1016/j.jacc.2026.07.025'),
 'resus':('AHA Special Circumstances of Resuscitation','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-and-pediatric-special-circumstances-of-resuscitation/')}
rows=[]
def B(t,*c):return(t,list(c))
def Q(title,stem,answer,others,sections,refs=('syncope',),table=None,ordered=(),flow=None):
 r=question('Pacing and ECG patterns' if len(rows)<7 else 'Syncope and autonomic assessment',title,stem,answer,others,sections,list(refs),table=table)
 r.update(explanationStyle='concise_structured',orderedSections=list(ordered))
 if flow:r['flow']=flow
 rows.append(r)

Q('Therapeutic Digoxin Effect','A stable patient taking digoxin has unchanged scooped lateral ST depression, mildly prolonged PR and a shortened QT. There are no new symptoms, ectopy or conduction block. Which interpretation is most appropriate?',
 'Therapeutic digoxin-related repolarization and AV nodal effects',[('Definite digoxin toxicity requiring antibody fragments','Toxicity requires integrated clinical/rhythm evidence; the stable characteristic repolarization effect alone does not establish life-threatening poisoning.'),('Acute subendocardial ischemia established by ST shape alone','Ischemia can coexist, but an unchanged characteristic drug pattern without ischemic symptoms does not establish acute coronary disease.'),('Hypokalemia as the necessary explanation','Hypokalemia can increase digoxin toxicity and produces U waves/flat T waves; it is not required to explain this stable therapeutic drug pattern.')],
 [('Drug Effect Versus Toxicity',[B('**Digoxin effect:** scooped ST depression, QT shortening and vagally mediated PR prolongation.','This pattern can occur at therapeutic exposure and is not a serum-level assay.')]),
 ('When to Suspect Toxicity',[B('**New GI/neurological symptoms, ectopy or AV block** require reassessment.','Atrial tachycardia with block and bidirectional VT are important toxic patterns.'),B('**Check renal function, potassium, magnesium and interacting drugs.**','Interpret a serum level with sampling time and clinical context; treat life-threatening toxicity rather than the ST shape alone.')])],refs=('resus',))

Q('Pacemaker Failure to Capture','A pacemaker-dependent patient becomes presyncopal. Ventricular pacing spikes occur regularly, but several are not followed by QRS complexes. What is the immediate device abnormality?',
 'Failure of ventricular capture',[('Ventricular oversensing','Oversensing generally inhibits expected output, causing absent spikes; here stimuli are visible but fail to depolarize the ventricle.'),('Ventricular undersensing','Undersensing causes inappropriate pacing despite intrinsic beats; it does not primarily describe a delivered stimulus lacking the expected QRS.'),('Normal fusion beats','Fusion combines intrinsic and paced activation into a QRS; a spike with no ventricular depolarization is not a fusion complex.')],
 [('Recognize Noncapture',[B('**Output is present but myocardial activation is absent.**','Causes include lead displacement/failure, rising threshold, metabolic disturbance and inadequate programmed output.')]),
 ('Urgent Response',[B('**Assess perfusion and provide backup pacing/resuscitation if unstable.**','A pacemaker-dependent patient can deteriorate rapidly; do not wait for routine clinic follow-up.'),B('**Arrange urgent interrogation**, check leads and reversible causes such as hyperkalemia/acidosis.','Output adjustment may restore capture, but correcting lead or metabolic pathology is essential; verify mechanical as well as electrical response.')])],refs=('pace',))

Q('Pacemaker Oversensing','A patient with a ventricular demand pacemaker develops pauses during arm movement. Interrogation shows rapid nonphysiological sensed signals and suppression of ventricular output during the pauses. What mechanism best fits?',
 'Oversensing of lead-related noise',[('Failure of myocardial capture','Capture failure requires delivered pacing stimuli without depolarization; output is being inhibited before a stimulus is delivered here.'),('Undersensing of intrinsic QRS complexes','Undersensing typically permits unnecessary pacing because intrinsic activity is missed; the device is instead detecting excessive inappropriate signals.'),('Normal rate-responsive pacing','Rate-response algorithms increase or adjust pacing with activity; they do not normally interpret lead noise as repeated intrinsic ventricular beats causing pauses.')],
 [('Mechanism',[B('**Inappropriate sensing resets/inhibits demand pacing.**','Lead fracture, insulation problems, myopotentials or electromagnetic interference can produce noise; movement association helps localize the cause.')]),
 ('Management',[B('**Assess dependence and instability**, provide backup support and obtain urgent device interrogation.'),B('**Review stored electrograms, impedance and lead integrity.**','Intermittent faults can escape a single normal measurement.'),B('**Magnet responses differ by device and programming.**','Do not assume that a magnet universally creates safe asynchronous pacing, especially in ICDs; use a device-specific supervised plan.')])],refs=('pace',))

Q('Pacemaker-Mediated Tachycardia','In a dual-chamber pacemaker, a ventricular premature beat is followed by retrograde atrial activation. Each subsequent atrial sensed event triggers ventricular pacing after the programmed AV delay, at the upper tracking rate. What mechanism best fits?',
 'Endless-loop pacemaker-mediated tachycardia',[('Sensor-driven rate-responsive tachycardia','Sensor-driven acceleration follows the activity/physiological sensor rather than a stable retrograde atrial–ventricular tracking loop initiated by a PVC.'),('Atrial flutter tracking','Flutter tracking originates from an independent rapid atrial rhythm; here each atrial signal follows ventricular activation retrogradely.'),('Ventricular tachycardia with incidental pacemaker spikes','The device is triggering each ventricular event after sensed atrial activity, supporting a device-mediated loop rather than an independent ventricular focus.')],
 [('Circuit',[B('**Retrograde VA conduction + atrial sensing + ventricular tracking** completes the loop.','A PVC or loss of AV synchrony can initiate it; rate is often limited by the upper tracking setting.')]),
 ('Terminate and Prevent',[B('**Device interrogation confirms the sequence.**','Programming a sufficiently long postventricular atrial refractory period prevents tracking of the retrograde P wave; PMT termination algorithms can help.'),B('**Distinguish true atrial tachyarrhythmia and sensor-driven pacing** before reprogramming.','Review VA timing and preserve appropriate exercise tracking; do not treat every paced tachycardia as intrinsic VT.')])],refs=('pace',))

Q('Hypothermic J Waves','A patient rescued after prolonged cold exposure has a core temperature of 29°C, sinus bradycardia and a prominent positive deflection at the QRS–ST junction in several leads. What is the most likely explanation?',
 'Hypothermia-associated Osborn waves',[('Acute territorial ST-elevation infarction','Acute occlusion remains a clinical differential, but diffuse J-point deflections with severe hypothermia and bradycardia fit temperature-related changes better than a single coronary territory.'),('Brugada type 1 pattern','Brugada requires characteristic coved right-precordial ST elevation with T inversion in the relevant context; generalized hypothermic J waves are not equivalent.'),('Hyperkalemia as the sole mechanism','Hyperkalemia commonly alters T waves, P waves and QRS conduction; the temperature-dependent QRS–ST notch is a characteristic hypothermic clue.')],
 [('ECG Effects',[B('**Hypothermia can produce J waves, bradycardia and prolonged intervals.**','J-wave size often increases as temperature falls; shivering artifact may obscure the tracing.')]),
 ('Clinical Care',[B('**Use controlled rewarming and continuous monitoring**, with gentle handling and correction of associated metabolic abnormalities.'),B('**J waves are not absolutely specific to hypothermia.**','Interpret temperature, lead distribution and symptoms; reassess persistent abnormalities after rewarming.'),B('**Severe hypothermia increases ventricular arrhythmia risk**, so the tracing should trigger appropriate resuscitation planning rather than isolated ECG labeling.')])],refs=('resus',))

Q('Wellens Pattern During a Pain-Free Interval','After recurrent chest pain has resolved, ECG shows deeply symmetric T-wave inversion in V2–V4 with preserved R waves and no substantial ST elevation. Troponin is not markedly elevated. What is the best next strategy?',
 'Urgent coronary evaluation while avoiding provocative exercise testing',[('Exercise treadmill testing to confirm inducible ischemia','Provocative stress can precipitate infarction in a Wellens-type high-risk coronary pattern; a low troponin does not establish safety.'),('Routine outpatient review because pain has resolved','Wellens changes commonly appear when pain-free and can signal a high-risk LAD lesion; symptom resolution does not justify delayed assessment.'),('Diagnose prior completed anterior infarction solely from T inversion','T inversion without pathological Q waves or loss of R progression does not prove a completed old infarct; the recent pain pattern suggests active coronary risk.')],
 [('Pattern and Context',[B('**Biphasic or deep symmetric anterior T inversion after pain resolves** is a high-risk reperfusion/ischemic pattern.','A severe LAD lesion is a classic association; normal or mildly elevated biomarkers do not exclude it.')]),
 ('Action and Differential',[B('**Urgent ACS/coronary assessment** is appropriate; avoid an exercise stress challenge.'),B('**Consider mimics** such as LVH, pulmonary embolism, CNS injury or cardiomyopathy when the clinical context differs.','ECG morphology supports a pathway but does not by itself establish exact coronary anatomy; use serial ECGs and definitive assessment.')])],refs=('udmi',))

Q('Exercise-Provoked Polymorphic Arrhythmia With Normal Resting ECG','A young person has exertional syncope, a normal resting QTc and normal cardiac imaging. Monitored exercise produces increasing ventricular ectopy followed by bidirectional and polymorphic VT. Which diagnosis is most likely?',
 'Catecholaminergic polymorphic ventricular tachycardia',[('Congenital long QT syndrome as the best fit','LQTS can cause exertional events and occasionally a normal resting QT, but progressive adrenergic bidirectional/polymorphic ectopy with normal structure is especially characteristic of CPVT.'),('Idiopathic RV outflow tract VT','RVOT VT is usually monomorphic with a consistent LBBB/inferior-axis morphology, unlike the escalating bidirectional/polymorphic pattern.'),('Brugada syndrome','Brugada events more often occur at rest/fever with a diagnostic right-precordial pattern; this exercise-dependent calcium-handling phenotype fits CPVT better.')],
 [('Electrical Phenotype',[B('**Resting ECG may be normal.**','Adrenergic stress reveals abnormal intracellular calcium handling; RYR2 is a common genetic cause, with other genes including CASQ2.')]),
 ('Management',[B('**Specialist inherited-arrhythmia care**, exercise/trigger counseling and nonselective beta-blockade, often nadolol.'),B('**Add flecainide for persistent arrhythmias** despite appropriate beta-blockade; assess left cardiac sympathetic denervation in refractory cases.'),B('**ICD decisions are individualized**, especially after arrest or refractory events.','Shocks can provoke adrenergic escalation; an ICD does not replace medication or specialist follow-up.')])],refs=('va',))

Q('Convulsive Syncope Versus Epileptic Seizure','During venepuncture, a patient becomes nauseated and pale, collapses, has several brief irregular jerks, and is oriented within seconds after being placed supine. Which interpretation is most likely?',
 'Reflex syncope with hypoperfusion-related myoclonic movements',[('Generalized tonic-clonic seizure established by any jerking','Brief myoclonus can occur during cerebral hypoperfusion; movements alone do not establish epilepsy when the trigger, pallor and rapid recovery favor syncope.'),('Psychogenic pseudosyncope solely because venepuncture is a trigger','Emotional/procedural triggers can cause genuine reflex hypotension; a functional diagnosis needs positive features and appropriate physiological correlation.'),('Cataplexy','Cataplexy causes emotion-triggered loss of tone with preserved awareness; this event includes true transient loss of consciousness and presyncopal autonomic symptoms.')],
 [('Discriminating History',[B('**Trigger, autonomic prodrome and rapid reorientation** support reflex syncope.','Brief arrhythmic jerks and urinary incontinence can occur in either syncope or seizure.')]),
 ('Avoid a Duration Myth',[B('**Generalized tonic-clonic seizures often last about 1–2 minutes**, followed by postictal impairment; they do not usually require >5 minutes to qualify.','Lateral tongue bite, stereotyped aura and prolonged confusion favor seizure, but no isolated sign replaces the full account.'),B('**Obtain witness history, examination, orthostatic vitals and ECG.**','Target EEG or neurological investigations to a credible seizure suspicion rather than reflexively ordering them for all fainting.')])],refs=('syncope','practical'))

Q('Classical Orthostatic Hypotension','After five minutes supine, BP is 142/82 mmHg. At one and three minutes of standing it is 116/72 and 114/70, with reproduced lightheadedness. Which diagnosis is supported?',
 'Classical orthostatic hypotension',[('Initial orthostatic hypotension','Initial OH is a transient marked fall within roughly 15 seconds of standing; a sustained fall at one and three minutes fits classical OH.'),('Delayed orthostatic hypotension','Delayed OH begins beyond three minutes; the clinically significant fall is already present within the first minute.'),('POTS','POTS requires orthostatic tachycardia without a sustained OH-range pressure fall; this patient has a clear sustained hypotensive response.')],
 [('Threshold and Timing',[B('**Sustained SBP fall ≥20 or DBP fall ≥10 mmHg within 3 minutes** meets the classical threshold.','The wording is within three minutes, not only a measurement after three minutes; ESC also recognizes sustained SBP <90 mmHg.')]),
 ('Determine the Cause',[B('**Review volume, drugs and autonomic symptoms.**','Blunted HR compensation can suggest neurogenic disease, but beta-blockers, pacing and conduction disease confound it.'),B('**Treat reversible contributors first**, then consider fluid/salt measures and compression when safe.','Supine hypertension, heart failure and renal disease limit indiscriminate volume expansion.')])],refs=('syncope','practical'))

Q('Postural Orthostatic Tachycardia Syndrome','A 24-year-old has six months of upright palpitations and lightheadedness relieved by lying down. HR rises from 70 to 108/min on repeated standing measurements within ten minutes; BP remains stable. Anemia, dehydration, thyroid disease and medication effects are excluded. Which diagnosis best fits?',
 'Postural orthostatic tachycardia syndrome',[('Classical orthostatic hypotension','Classical OH requires a sustained pressure fall; stable BP with a sustained symptomatic tachycardic response supports a different orthostatic syndrome.'),('Inappropriate sinus tachycardia','IST more often includes excessive resting/average heart rate and symptoms beyond posture; a normal supine HR with a reproducible upright response favors POTS.'),('Paroxysmal AV nodal reentrant tachycardia','AVNRT typically starts and stops abruptly as a reentrant rhythm; the sustained posture-linked sinus acceleration described here is not that pattern.')],
 [('Required Features',[B('**Sustained HR rise ≥30/min in adults** within ten minutes; ≥40/min for ages 12–19.','Require chronic orthostatic symptoms, generally ≥3 months, no sustained OH-range BP fall and no better explanation.')]),
 ('Assessment and Care',[B('**Repeat standardized supine-to-standing HR/BP measurements.**','A single transient peak is insufficient; consider morning variability and confounders.'),B('**Begin individualized fluid/salt, compression and graded exercise measures** when appropriate.','Medication selection depends on HR, pressure and symptoms; POTS is not diagnosed solely from a wearable pulse alert or from unexplained fatigue.')])],refs=('pots','practical'))

Q('Monitoring Infrequent Unexplained Syncope','A patient has recurrent unexplained syncope every three to four months. Initial assessment and echo are unrevealing, and there is no indication for immediate ICD/pacing or inpatient high-risk treatment. Which strategy best seeks symptom–rhythm correlation?',
 'Implantable loop recorder',[('A single 24-hour Holter recording','Holter is useful when symptoms are frequent; a one-day window is unlikely to capture an event recurring every few months.'),('A 48-hour inpatient telemetry admission as the definitive long-term test','Telemetry is appropriate for immediate high-risk assessment but a brief admission has low yield for this infrequent stable recurrence pattern.'),('Routine invasive EPS in every such patient','EPS is useful in selected substrates or conduction disease; it is not the highest-yield universal test in a structurally reassuring, infrequent-event presentation.')],
 [('Match Monitoring to Event Frequency',[B('**Long-term recording increases the chance of capturing the spontaneous event.**','The objective is a rhythm correlated with symptoms, not merely incidental ectopy.')]),
 ('Selection and Interpretation',[B('**ILR is appropriate in selected recurrent unexplained syncope** when recurrence is likely and immediate high-risk therapy is not required.'),B('**A normal short monitor does not exclude arrhythmia.**','External monitoring suits sufficiently frequent episodes; high-risk findings require prompt evaluation rather than waiting months for an ILR event.'),B('**Continue assessment for nonarrhythmic causes** even after implantation.')])],refs=('syncope',))

Q('Interpreting a Positive Tilt Test','A patient with an uncertain history has typical symptoms reproduced on tilt, preceded by progressive hypotension and then bradycardia. What is the most appropriate conclusion?',
 'The result demonstrates susceptibility to a reflex hypotensive response, interpreted with the spontaneous history',[('It excludes an arrhythmic cause for every previous event','Reflex susceptibility can coexist with cardiac disease; a positive tilt does not prove that all spontaneous episodes share the same mechanism.'),('It establishes a pacemaker indication from hypotension alone','Pacing targets selected cardioinhibitory mechanisms and cannot directly reverse vasodilation; tilt-induced hypotension alone is not sufficient.'),('It establishes epilepsy because consciousness was lost during testing','Loss of consciousness with documented hypotension/bradycardia supports hypoperfusion; epileptic diagnosis requires different supporting evidence.')],
 [('Physiological Meaning',[B('**Tilt reproduces symptoms with monitored HR and BP.**','The timing of hypotension versus bradycardia helps characterize vasodepressor, cardioinhibitory or mixed responses.')]),
 ('Limits',[B('**A positive result is contextual evidence**, not a universal explanation of every attack.','A negative result does not exclude reflex syncope either.'),B('**Tilt can also evaluate delayed OH or apparent functional events** using appropriate physiological recording.'),B('**Use the spontaneous history and risk profile** to decide whether additional rhythm or structural assessment is still needed.')])],refs=('syncope','practical'))

Q('Carotid Sinus Hypersensitivity Versus Syndrome','During appropriately monitored carotid sinus massage in a 72-year-old with unexplained falls, a 4-second pause occurs but no spontaneous-type symptom is reproduced. What is the most defensible interpretation?',
 'Carotid sinus hypersensitivity; carotid sinus syndrome is not established by the pause alone',[('Definite carotid sinus syndrome requiring pacing regardless of symptom correlation','Asymptomatic hypersensitivity is common in older people; syndrome diagnosis requires reproduction of compatible spontaneous symptoms and clinical correlation.'),('A normal response because asystole is less than six seconds','A pause exceeding three seconds meets the conventional hypersensitivity criterion; absence of symptoms limits the syndrome inference rather than making the response normal.'),('Proof of intrinsic sinus node disease','A provoked reflex pause does not by itself establish intrinsic sinus-node failure; mechanism and spontaneous rhythm evidence must be distinguished.')],
 [('Diagnostic Distinction',[B('**Hypersensitivity:** ventricular pause >3 seconds and/or SBP fall >50 mmHg during massage.','Carotid sinus syndrome requires compatible spontaneous events reproduced by the test; symptom-producing pauses are often longer.')]),
 ('Safe Testing',[B('**Use ECG and beat-to-beat BP monitoring** in an appropriate clinical setting, usually age >40 with a compatible unexplained reflex presentation.'),B('**Assess cerebrovascular/carotid contraindications first.**','Recent stroke/TIA or significant carotid stenosis requires avoidance or specialist risk assessment; the test is not an unmonitored bedside experiment.')])],refs=('syncope','practical'))

Q('Counterpressure Maneuvers in Reflex Syncope','A patient with recurrent vasovagal episodes consistently has 30–60 seconds of warmth, nausea and visual dimming before collapse. Which preventive action is most appropriate at the onset of this prodrome?',
 'Sit or lie safely, with leg/abdominal muscle tensing or handgrip while still able',[('Remain upright and walk briskly to restore blood pressure','Walking during evolving presyncope risks a fall; reducing orthostatic stress and using safe counterpressure are more appropriate.'),('Take an extra beta-blocker dose immediately','Beta-blockade does not provide rapid rescue from reflex hypotension and may blunt compensatory responses; it is not the appropriate prodromal action.'),('Use breath-holding with prolonged straining as the main maneuver','A sustained Valsalva strain can reduce venous return; it differs from evidence-based muscle counterpressure with safe posture.')],
 [('Mechanism',[B('**Muscle contraction increases venous return and vascular resistance.**','Leg crossing with tensing, buttock/abdominal contraction and handgrip can delay or abort a prodromal episode.')]),
 ('Selection and Safety',[B('**A recognizable prodrome is essential.**','Sudden unwarned events may not allow a maneuver and need further risk assessment.'),B('**Lie down before attempting to walk elsewhere.**','Avoid injury; use hydration, trigger avoidance and salt measures only when compatible with BP, cardiac and renal status.'),B('**Persistent injurious recurrence warrants reassessment**, rather than relying solely on self-rescue maneuvers.')])],refs=('syncope',))

Q('Midodrine for Recurrent Vasovagal Syncope','A young adult with a low-BP phenotype continues frequent vasovagal syncope despite education, hydration and counterpressure training. There is no hypertension or urinary retention. Which drug reduced recurrence in POST-4 and is a reasonable option?',
 'Midodrine',[('Metoprolol','Beta-blockers have not shown reliable benefit for typical young vasovagal patients; metoprolol was not the intervention tested in POST-4.'),('Paroxetine','SSRIs have been studied in selected refractory patients, but evidence is limited and heterogeneous; paroxetine was not the POST-4 intervention.'),('Fludrocortisone','Volume expansion can help selected low-BP patients, but fludrocortisone was evaluated in POST-2; it was not the drug producing the stated POST-4 result.')],
 [('Evidence and Action',[B('**Midodrine is an alpha-1 agonist** that supports vascular tone.','POST-4 found recurrence in 42% with midodrine versus 61% with placebo in a selected predominantly young population; benefit is not universal.')]),
 ('Practical Use',[B('**Typically 2.5–10 mg three times daily during waking hours**, titrated to symptoms and pressure.','Avoid dosing near bedtime, commonly within four hours; monitor supine BP.'),B('**Watch urinary retention, scalp tingling and piloerection.**','Evidence in selected low-risk patients should not replace investigation of possible cardiac syncope or treatment of orthostatic drug/volume causes.')])],refs=('syncope','post4'))

Q('Fludrocortisone Safety in Orthostatic Hypotension','A patient with orthostatic symptoms starts fludrocortisone and subsequently develops ankle edema, higher supine BP and potassium 3.1 mmol/L. Which mechanism best explains the adverse-effect cluster?',
 'Mineralocorticoid-mediated sodium retention and renal potassium loss',[('Direct alpha-1 vasoconstriction without volume expansion','That describes midodrine more closely; the edema and potassium loss point to mineralocorticoid action.'),('Acetylcholinesterase inhibition at autonomic ganglia','Pyridostigmine has cholinergic effects such as diarrhea and salivation; it does not explain this sodium-retention pattern.'),('Norepinephrine precursor conversion','Droxidopa can raise supine BP but is not a mineralocorticoid and does not characteristically cause this potassium-wasting cluster.')],
 [('Drug Mechanism',[B('**Fludrocortisone expands extracellular volume** and can increase vascular responsiveness.','Typical low doses are 0.05–0.1 mg daily, cautiously up to about 0.2 mg/day in selected patients.')]),
 ('Monitoring and Response',[B('**Review or reduce treatment and correct potassium as appropriate.**','Monitor weight, edema, supine/standing pressure and renal function.'),B('**Heart failure, significant edema and supine hypertension limit use.**','Volume expansion is not benign; reconsider reversible causes, abdominal compression and alternative strategies rather than escalating automatically.'),B('**Treatment aims to improve upright function**, not simply normalize every BP reading.')])],refs=('syncope',))

Q('Pacing Selected Reflex Syncope','A 66-year-old has severe recurrent unpredictable syncope with injuries despite conservative care. An ILR records an 8-second asystolic pause during a typical event; reversible causes have been excluded. Which strategy is supported?',
 'Evaluate for dual-chamber pacing for documented cardioinhibitory reflex syncope',[('Use pacing only if the baseline resting HR is below 40/min','Intermittent symptomatic asystole can justify pacing despite a normal resting rate; a persistent bradycardia threshold is not required here.'),('Withhold pacing because all reflex syncope is purely vasodepressor','Reflex events can have a dominant cardioinhibitory component; documented symptomatic asystole in a selected older patient changes the treatment options.'),('Implant an ICD because any prolonged pause predicts ventricular fibrillation','An asystolic reflex event is not itself an ICD indication; defibrillation addresses malignant tachyarrhythmia risk, not this documented mechanism.')],
 [('Selection',[B('**Selected patients >40 with severe recurrent unpredictable events and documented asystole** may benefit from dual-chamber pacing.','Common spontaneous pause thresholds: >3 seconds with symptoms or >6 seconds without symptoms, interpreted in the full clinical setting.')]),
 ('Evidence and Limitations',[B('**BioSync CLS supports selected older patients with tilt-induced asystole**, not indiscriminate pacing of young typical fainters.'),B('**Pacing cannot directly correct vasodilation.**','A major hypotensive component may still cause recurrence; continue preventive measures and realistic counseling.'),B('**Establish symptom–rhythm correlation** and exclude reversible bradycardia before an implant decision.')])],refs=('pace','biosync'))

Q('Syncope During Versus After Exercise','Two athletes faint: patient A loses consciousness while sprinting without warning; patient B becomes nauseated and faints after stopping abruptly in heat. Which interpretation should guide the initial evaluation?',
 'During-exercise syncope in A raises greater concern for structural or arrhythmic disease',[('Both events establish benign vasovagal syncope because the patients are athletes','Athletic status does not exclude cardiomyopathy, coronary anomalies or channelopathy; abrupt loss during exertion needs urgent risk assessment.'),('Postexercise timing in B proves a malignant ventricular arrhythmia','Postexercise muscle-pump withdrawal and persistent vasodilation can cause reflex/orthostatic syncope; the autonomic prodrome supports that possibility.'),('A normal resting ECG would exclude cardiac disease in A','CPVT and some structural/coronary disorders may have a normal resting ECG; the exertional history still warrants directed testing.')],
 [('Mechanisms',[B('**During exertion:** consider outflow obstruction, ischemia, coronary anomaly or exercise-triggered arrhythmia.','After stopping, venous pooling and ongoing vasodilation can precipitate reflex hypotension.')]),
 ('Investigate Safely',[B('**History, examination and ECG are initial requirements.**','Use echo and supervised exercise/rhythm assessment according to findings; do not prescribe an unsupervised exertional challenge.'),B('**Assess family history and previous episodes**, and restrict risky activity pending clarification when cardiac syncope is suspected.'),B('**Timing informs probability, not certainty**; persistent high-risk features in either patient require evaluation.')])],refs=('syncope','va'))

Q('Psychogenic Pseudosyncope','During a monitored tilt/video-EEG study, a typical prolonged episode of apparent unresponsiveness occurs with closed eyes, preserved BP and HR, and normal waking EEG activity. What diagnosis is most strongly supported?',
 'Psychogenic pseudosyncope',[('Vasodepressor syncope','Genuine vasodepressor syncope requires a fall in perfusion pressure; stable measured hemodynamics and preserved waking EEG during the typical event argue against it.'),('Generalized epileptic seizure','The recorded typical episode lacks an ictal pattern and shows preserved waking activity; the evidence favors a functional event rather than generalized epileptic loss of consciousness.'),('Cardioinhibitory syncope','A cardioinhibitory event would show clinically relevant bradycardia/asystole with hypoperfusion, absent during this recorded episode.')],
 [('Positive Diagnosis',[B('**A typical attack recorded without hemodynamic or EEG evidence of cerebral hypoperfusion** provides positive diagnostic evidence.','Closed eyes and long duration are clues, not standalone proof; verify the episode resembles spontaneous events.')]),
 ('Explain and Treat',[B('**Describe the condition respectfully as involuntary and real.**','Avoid suggesting fabrication; offer a clear explanation and appropriate psychological/functional-disorder care.'),B('**Consider coexisting true syncope or epilepsy** when other event types differ.'),B('**Do not diagnose by normal interepisode tests alone** or simply by the presence of anxiety.')])],refs=('syncope','practical'))

Q('Hyperkalemia With a Reassuring ECG','A patient with advanced CKD has confirmed nonhemolyzed potassium 7.0 mmol/L, but QRS duration and T waves are not strikingly abnormal. Which conclusion is correct?',
 'A normal-looking ECG does not exclude dangerous hyperkalemia or remove the need for urgent treatment',[('The potassium result must be artifactual because ECG changes are absent','Pseudohyperkalemia requires sampling/clinical assessment; a confirmed result cannot be dismissed solely because the ECG lacks classic changes.'),('Treatment can wait until QRS widening appears','ECG changes do not follow a reliable obligatory sequence; waiting for conduction failure risks sudden deterioration.'),('Only calcium is needed because it removes potassium rapidly','IV calcium stabilizes the myocardium when indicated but does not lower total body potassium; shifting and elimination strategies address the potassium burden.')],
 [('ECG Limitations',[B('**ECG sensitivity is limited**, and severity depends on rate of rise, acid–base state and underlying disease.','Peaked T waves, loss of P waves and QRS widening are important when present but may not progress sequentially.')]),
 ('Urgent Management',[B('**Monitor, confirm the context and treat the severe biochemical abnormality.**','Use appropriate intracellular-shift measures and potassium removal, including dialysis when indicated; monitor glucose with insulin therapy.'),B('**Calcium is membrane stabilization**, especially with toxic ECG changes or instability, rather than potassium removal.'),B('**Recheck potassium and watch rebound** after temporary shifting treatments.')])],refs=('resus',))
